CREATE DATABASE IF NOT EXISTS bidrush CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bidrush;
CREATE TABLE users (id CHAR(36) PRIMARY KEY,email VARCHAR(254) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,display_name VARCHAR(80) NOT NULL,role ENUM('client','freelancer','admin','moderator') NOT NULL DEFAULT 'client',status ENUM('pending','active','suspended','closed') NOT NULL DEFAULT 'pending',email_verified_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE freelancer_profiles (user_id CHAR(36) PRIMARY KEY,headline VARCHAR(120) NULL,bio TEXT NULL,skills JSON NULL,rating_avg DECIMAL(3,2) NOT NULL DEFAULT 0,completed_jobs INT UNSIGNED NOT NULL DEFAULT 0,response_rate DECIMAL(5,2) NOT NULL DEFAULT 0,is_online BOOLEAN NOT NULL DEFAULT FALSE,verified_at TIMESTAMP NULL,CONSTRAINT fk_freelancer_user FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE tasks (id CHAR(36) PRIMARY KEY,client_id CHAR(36) NOT NULL,title VARCHAR(160) NOT NULL,description TEXT NOT NULL,category VARCHAR(60) NOT NULL,currency CHAR(3) NOT NULL DEFAULT 'USD',max_budget DECIMAL(12,2) NOT NULL,deadline_at TIMESTAMP NOT NULL,auction_starts_at TIMESTAMP NOT NULL,auction_ends_at TIMESTAMP NOT NULL,status ENUM('draft','scheduled','live','awarded','in_progress','submitted','completed','cancelled','disputed') NOT NULL DEFAULT 'draft',winner_bid_id CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_tasks_status_ends(status,auction_ends_at),INDEX idx_tasks_client(client_id),CONSTRAINT fk_task_client FOREIGN KEY(client_id) REFERENCES users(id));
CREATE TABLE bids (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,freelancer_id CHAR(36) NOT NULL,amount DECIMAL(12,2) NOT NULL,note VARCHAR(500) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_bids_task_amount(task_id,amount),INDEX idx_bids_freelancer(freelancer_id),CONSTRAINT fk_bid_task FOREIGN KEY(task_id) REFERENCES tasks(id),CONSTRAINT fk_bid_freelancer FOREIGN KEY(freelancer_id) REFERENCES users(id));
CREATE TABLE task_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,task_id CHAR(36) NOT NULL,actor_id CHAR(36) NULL,event_type VARCHAR(50) NOT NULL,payload JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_task_events_task_time(task_id,created_at),CONSTRAINT fk_event_task FOREIGN KEY(task_id) REFERENCES tasks(id));
CREATE TABLE deposits (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,client_id CHAR(36) NOT NULL,amount DECIMAL(12,2) NOT NULL,platform_deposit_fee DECIMAL(12,2) NOT NULL DEFAULT 0,currency CHAR(3) NOT NULL DEFAULT 'USD',provider VARCHAR(40) NULL,provider_reference VARCHAR(150) NULL,status ENUM('pending','authorized','captured','refunded','failed') NOT NULL DEFAULT 'pending',idempotency_key VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_deposits_task(task_id),CONSTRAINT fk_deposit_task FOREIGN KEY(task_id) REFERENCES tasks(id),CONSTRAINT fk_deposit_client FOREIGN KEY(client_id) REFERENCES users(id));
CREATE TABLE work_submissions (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,freelancer_id CHAR(36) NOT NULL,message TEXT NULL,attachment_refs JSON NULL,status ENUM('submitted','accepted','revision_requested','rejected') NOT NULL DEFAULT 'submitted',submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP NULL,CONSTRAINT fk_submission_task FOREIGN KEY(task_id) REFERENCES tasks(id),CONSTRAINT fk_submission_freelancer FOREIGN KEY(freelancer_id) REFERENCES users(id));
CREATE TABLE reviews (id CHAR(36) PRIMARY KEY,task_id CHAR(36) NOT NULL,reviewer_id CHAR(36) NOT NULL,reviewee_id CHAR(36) NOT NULL,rating TINYINT UNSIGNED NOT NULL,comment VARCHAR(1000) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_review_task_reviewer(task_id,reviewer_id),CONSTRAINT chk_review_rating CHECK(rating BETWEEN 1 AND 5),CONSTRAINT fk_review_task FOREIGN KEY(task_id) REFERENCES tasks(id),CONSTRAINT fk_review_reviewer FOREIGN KEY(reviewer_id) REFERENCES users(id),CONSTRAINT fk_review_reviewee FOREIGN KEY(reviewee_id) REFERENCES users(id));
